        [Fact]
        public async Task Test_MarkdownHiddenExcludedByDefault()
        {
            // HTTP Markdown excludes hidden elements and template text by default while preserving visible text
            var engineConfig = JsonSerializer.Deserialize<CrawlConfig>("{\"browser\":{\"mode\":\"never\"},\"content\":{\"extract_metadata\":false}}", ConfigOptions)!;
            var engine = CrawlbergConverter.CreateEngine(engineConfig);
            var url = Environment.GetEnvironmentVariable("MOCK_SERVER_URL") + "/fixtures/markdown_hidden_excluded_by_default";
            var result = await CrawlbergConverter.ScrapeAsync(engine, url);
            Assert.True(result.StatusCode == 200);
            Assert.Contains("Visible sentence.", result.Markdown!.Content.ToString());
            Assert.DoesNotContain("Hidden attribute sentence.", result.Markdown!.Content.ToString());
            Assert.DoesNotContain("Display none sentence.", result.Markdown!.Content.ToString());
            Assert.DoesNotContain("Template sentence.", result.Markdown!.Content.ToString());

        }

